  "inlineSchema": "// Prisma schema for Subscription Microservice\n// Multi-tenant model with RBAC, plans, subscriptions, and payment tracking\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ============================================\n// TENANTS\n// ============================================\nmodel Tenant {\n  id                  String       @id @default(uuid())\n  name                String\n  slug                String       @unique\n  domain              String?      @unique\n  status              TenantStatus @default(ACTIVE)\n  paymentProvider     String? // 'stripe' | 'paypal' | etc.\n  gatewayConfiguredAt DateTime?\n  createdAt           DateTime     @default(now())\n  updatedAt           DateTime     @updatedAt\n\n  users         User[]\n  plans         Plan[]\n  subscriptions Subscription[]\n  invoices      Invoice[]\n\n  @@map(\"tenants\")\n}\n\nenum TenantStatus {\n  ACTIVE\n  SUSPENDED\n  DELETED\n}\n\n// ============================================\n// USERS\n// ============================================\nmodel User {\n  id           String     @id @default(uuid())\n  email        String     @unique\n  passwordHash String\n  firstName    String?\n  lastName     String?\n  status       UserStatus @default(ACTIVE)\n  createdAt    DateTime   @default(now())\n  updatedAt    DateTime   @updatedAt\n\n  // Platform-level (no tenantId) vs tenant-level\n  tenantId String?\n  tenant   Tenant? @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  roles         UserRole[]\n  subscriptions Subscription[]\n\n  @@index([tenantId])\n  @@index([email])\n  @@map(\"users\")\n}\n\nenum UserStatus {\n  ACTIVE\n  INVITED\n  SUSPENDED\n  DELETED\n}\n\n// ============================================\n// ROLES & RBAC\n// ============================================\nmodel Role {\n  id          String    @id @default(uuid())\n  name        String    @unique // 'super_admin', 'tenant_owner', etc.\n  scope       RoleScope\n  description String?\n  createdAt   DateTime  @default(now())\n\n  userRoles UserRole[]\n\n  @@map(\"roles\")\n}\n\nenum RoleScope {\n  PLATFORM\n  TENANT\n}\n\nmodel UserRole {\n  id     String @id @default(uuid())\n  userId String\n  roleId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  role   Role   @relation(fields: [roleId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, roleId])\n  @@index([userId])\n  @@map(\"user_roles\")\n}\n\n// ============================================\n// PLANS\n// ============================================\nmodel Plan {\n  id            String          @id @default(uuid())\n  tenantId      String\n  tenant        Tenant          @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  name          String\n  description   String?\n  amount        Decimal         @db.Decimal(10, 2)\n  currency      String          @default(\"USD\")\n  interval      BillingInterval\n  intervalCount Int             @default(1)\n  trialDays     Int             @default(0)\n  gatewayPlanId String? // Provider-side plan ID (Stripe price ID, etc.)\n  isActive      Boolean         @default(true)\n  createdAt     DateTime        @default(now())\n  updatedAt     DateTime        @updatedAt\n\n  subscriptions Subscription[]\n\n  @@index([tenantId])\n  @@map(\"plans\")\n}\n\nenum BillingInterval {\n  DAY\n  WEEK\n  MONTH\n  YEAR\n}\n\n// ============================================\n// SUBSCRIPTIONS\n// ============================================\nmodel Subscription {\n  id                    String             @id @default(uuid())\n  tenantId              String\n  tenant                Tenant             @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  userId                String\n  user                  User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  planId                String\n  plan                  Plan               @relation(fields: [planId], references: [id])\n  status                SubscriptionStatus @default(ACTIVE)\n  gatewayProvider       String // 'stripe', 'paypal', etc.\n  gatewaySubscriptionId String? // Provider-side ID\n  gatewayCustomerId     String?\n  currentPeriodStart    DateTime\n  currentPeriodEnd      DateTime\n  cancelAtPeriodEnd     Boolean            @default(false)\n  cancelledAt           DateTime?\n  createdAt             DateTime           @default(now())\n  updatedAt             DateTime           @updatedAt\n\n  invoices Invoice[]\n\n  @@index([tenantId])\n  @@index([userId])\n  @@index([status])\n  @@map(\"subscriptions\")\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  TRIALING\n  PAST_DUE\n  CANCELLED\n  PAUSED\n  EXPIRED\n}\n\n// ============================================\n// INVOICES\n// ============================================\nmodel Invoice {\n  id               String        @id @default(uuid())\n  tenantId         String\n  tenant           Tenant        @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  subscriptionId   String?\n  subscription     Subscription? @relation(fields: [subscriptionId], references: [id])\n  amount           Decimal       @db.Decimal(10, 2)\n  currency         String        @default(\"USD\")\n  status           InvoiceStatus @default(PENDING)\n  gatewayInvoiceId String?\n  paidAt           DateTime?\n  createdAt        DateTime      @default(now())\n  updatedAt        DateTime      @updatedAt\n\n  @@index([tenantId])\n  @@index([subscriptionId])\n  @@index([status])\n  @@map(\"invoices\")\n}\n\nenum InvoiceStatus {\n  PENDING\n  PAID\n  FAILED\n  REFUNDED\n  VOID\n}\n",
